using System.Collections.Generic;
using DG.DemiLib;
using UnityEngine;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "RunModifierHandler", menuName = "Data/RunModifiers/RunModifierHandler", order = 0)]
public class RunModifiersHandler : ScriptableObject
{
	[Header("Variables")]
	[SerializeField]
	private IntRange amountOfRunModifiersRange;

	[SerializeField]
	private int oneGoodModifierPercentage;

	[Header("Active")]
	public List<RunModifier> ActiveRunModifiers = new List<RunModifier>();

	[Header("List")]
	public List<RunModifier> AllRunModifiersList = new List<RunModifier>();

	public List<RunModifier> GetRandomizedRunModifiers(bool dailyRun)
	{
		int num = 2;
		if (RandomUtilities.RandomChanceWithSeed(oneGoodModifierPercentage))
		{
			num = 1;
		}
		List<RunModifier> list = new List<RunModifier>();
		List<RunModifier> allRunModifiersListDuplicatedWithoutRunModifiersOnly = GetAllRunModifiersListDuplicatedWithoutRunModifiersOnly();
		allRunModifiersListDuplicatedWithoutRunModifiersOnly.RemoveAll((RunModifier runModifier) => runModifier.RunModifierType == RunModifierType.GOOD);
		if (!dailyRun)
		{
			allRunModifiersListDuplicatedWithoutRunModifiersOnly.RemoveAll((RunModifier runModifier) => runModifier.DailyRunOnly);
		}
		List<RunModifier> allRunModifiersListDuplicatedWithoutRunModifiersOnly2 = GetAllRunModifiersListDuplicatedWithoutRunModifiersOnly();
		allRunModifiersListDuplicatedWithoutRunModifiersOnly2.RemoveAll((RunModifier runModifier) => runModifier.RunModifierType != RunModifierType.GOOD);
		if (!dailyRun)
		{
			allRunModifiersListDuplicatedWithoutRunModifiersOnly2.RemoveAll((RunModifier runModifier) => runModifier.DailyRunOnly);
		}
		for (int i = 0; i < num; i++)
		{
			RunModifier runModifierPicked2 = allRunModifiersListDuplicatedWithoutRunModifiersOnly2.PopRandom();
			list.Add(runModifierPicked2);
			allRunModifiersListDuplicatedWithoutRunModifiersOnly2.RemoveAll((RunModifier runModifier) => runModifierPicked2.RunModifiersToMute.Contains(runModifier));
			allRunModifiersListDuplicatedWithoutRunModifiersOnly.RemoveAll((RunModifier runModifier) => runModifierPicked2.RunModifiersToMute.Contains(runModifier));
		}
		int num2 = RandomUtilities.RandomIntWithSeed(amountOfRunModifiersRange.min, amountOfRunModifiersRange.max + 1) - num;
		List<RunModifierType> list2 = new List<RunModifierType>();
		list2.Add(RunModifierType.BAD);
		list2.Add(RunModifierType.BAD);
		list2.Add(RunModifierType.NEUTRAL);
		list2.Add(RunModifierType.NEUTRAL);
		List<RunModifier> list3 = allRunModifiersListDuplicatedWithoutRunModifiersOnly.Duplicate();
		list3.RemoveAll((RunModifier runModifier) => runModifier.RunModifierType != RunModifierType.BAD);
		List<RunModifier> list4 = allRunModifiersListDuplicatedWithoutRunModifiersOnly.Duplicate();
		list4.RemoveAll((RunModifier runModifier) => runModifier.RunModifierType != RunModifierType.NEUTRAL);
		for (int j = 0; j < num2; j++)
		{
			RunModifierType runModifierType = list2.PopRandom();
			RunModifier runModifierPicked = null;
			switch (runModifierType)
			{
			case RunModifierType.BAD:
				runModifierPicked = list3.PopRandom();
				break;
			case RunModifierType.NEUTRAL:
				runModifierPicked = list4.PopRandom();
				break;
			}
			list.Add(runModifierPicked);
			list3.RemoveAll((RunModifier runModifier) => runModifierPicked.RunModifiersToMute.Contains(runModifier));
			list4.RemoveAll((RunModifier runModifier) => runModifierPicked.RunModifiersToMute.Contains(runModifier));
		}
		return list;
	}

	private List<RunModifier> GetAllRunModifiersListDuplicatedWithoutRunModifiersOnly()
	{
		List<RunModifier> list = AllRunModifiersList.Duplicate();
		list.RemoveAll((RunModifier runModifier) => runModifier.RunModifierOnly);
		return list;
	}

	public RunModifier GetRunModifier(string runModifierName)
	{
		for (int i = 0; i < AllRunModifiersList.Count; i++)
		{
			if (runModifierName.ToLower().Replace(" ", "") == AllRunModifiersList[i].name.ToLower().Replace(" ", ""))
			{
				return AllRunModifiersList[i];
			}
		}
		return null;
	}
}
